code.text:
// Most routes
{ "error": "invalid input: text is required" }

// Some domains (connections, controls, drive, shop...) add a stable code
{ "error": "conflict: not enough coins", "code": "insufficient_coins" }

// /auth/* routes and permission failures
{ "error": { "code": "forbidden", "message": "insufficient permissions" } }

// Auth validation (422) lists the fields that failed
{ "error": { "code": "validation_failed", "message": "invalid input",
             "fields": { "password": "..." } } }

# Browsers cannot set headers on a WebSocket: pass the token in the query string
wscat -c 'ws://localhost:8080/ws?access_token=<token>'

< {"id":"...","type":"hello","ts":"...","org_id":"<org id>","payload":{"agents":[...]}}
< {"id":"...","type":"agent.state_changed","ts":"...","org_id":"<org id>","agent_id":"sales","payload":{...}}

# Frame shape
{ "id": "<uuid>", "type": "<event.type>", "ts": "<RFC 3339>",
  "org_id": "<org id>", "agent_id": "<optional>", "payload": { } }

